-- wa261_drive_forms (16/10/26): the Holiday Gift Basket Drive's pop-up forms, the CRM's form groups, and the gift counter.
-- Steel, 16/10/26: "I think we should have a new volunteer application form via the hub so that we can collect them on that
-- page as a pop-up form, to donate gifts and essentials, to volunteer with us. I don't want it to bring people to a
-- different page. I want it to pop up a form for each of those actions that they can take. Same thing for companies and
-- sponsors and schools and groups. The forms in the CRM need to be maybe grouped. We can maybe group forms for different
-- purposes, like volunteers." Earlier the same day: a gift counter on the drive's page (gifts collected toward the 6,000
-- goal), "this should be editable".
--   1. crm_forms.purpose: the form groups (Volunteers, Gifts and in-kind donations, Sponsors and partners, Schools and
--      groups, Other); every existing form assigned.
--   2. campaign_gifts: the drive's gifts in kind, batch by batch (staff with the Fundraising app; no anonymous access).
--      Counted on the website: received batches, and pledges a staff member confirmed. A pledge from the website form waits
--      for a Confirm, so the public number never grows from an unverified submission. Seeded with the first donation (616
--      books, reported by Amanda on 15/10/26).
--   3. wa261_gifts(slug) and wa261_gift_save(jsonb): the Fundraising app's Gifts collected box reads and writes through them
--      (checks inside: wa_fund_ok()).
--   4. www_campaign_totals gains gifts_in (the counted gifts in kind). Aggregates only, as before.
--   5. The Request type gift-drive (Fundraising, assigned to Amanda, posted brief: the details stay in the Hub), and
--      crm_form_apply: a form with settings.request files a Request for each real answer; settings.gift_pledge turns the
--      answer into a pledged campaign_gifts row; settings.role_text names what a volunteer applied for in Applicants
--      received; an address at a reserved test domain (example.com, .test and the like) is handled as a test everywhere.
--   6. The eight forms (four, in English and French), live, generated by build/data/wa261_forms.py.

/* ---------- 1. the form groups ---------- */
alter table public.crm_forms add column if not exists purpose text not null default 'other';
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'crm_forms_purpose_check') then
    alter table public.crm_forms add constraint crm_forms_purpose_check check (purpose in ('volunteers', 'gifts', 'sponsors', 'groups', 'other'));
  end if;
end $$;
comment on column public.crm_forms.purpose is 'wave261 (16/10/26, Steel: "group forms for different purposes, like volunteers"): the group the CRM''s Forms tab lists the form under: volunteers (Volunteers), gifts (Gifts and in-kind donations), sponsors (Sponsors and partners), groups (Schools and groups) or other (Other). Staff with the CRM pick it in the form editor. It changes nothing about what the form does with an answer.';
update public.crm_forms set purpose = case
    when slug in ('volunteer', 'toronto-volunteer', 'benevole') then 'volunteers'
    when slug in ('group', 'groupe') then 'groups'
    else 'other' end
 where purpose = 'other';
comment on column public.crm_forms.settings is 'volunteer_record (true: an application also creates or updates the MTL volunteering record), serving_location (the events a serving_dates question offers), city (written on new contacts), tags (added to the contact), confirm and confirm_template (a confirmation email through mail-send; off unless Steel turns it on). wave261: campaign (a slug of app_config donate_campaigns, e.g. gift-basket-drive: the form belongs to that campaign), request ({type, title, who, count, count_word}: each real answer files a Request of that request_types key, titled "<title>: <the who answer or the first name>", details without email or phone), gift_pledge (true: the answers how_many and what become a pledged campaign_gifts row that waits for a staff Confirm), role_text and role_q (what Applicants received says a volunteer applied for: role_text plus the picked choices of question role_q).';

/* ---------- 2. the gifts in kind ---------- */
create table if not exists public.campaign_gifts (
  id bigint generated always as identity primary key,
  slug text not null check (slug ~ '^[a-z0-9][a-z0-9-]{0,39}$'),
  quantity integer not null check (quantity > 0 and quantity <= 1000000),
  what text check (what is null or char_length(what) <= 300),
  given_by text check (given_by is null or char_length(given_by) <= 200),
  contact_id bigint references public.crm_contacts(id) on delete set null,
  received_on date,
  status text not null default 'received' check (status in ('pledged', 'received')),
  confirmed_at timestamptz,
  confirmed_by text,
  note text check (note is null or char_length(note) <= 2000),
  source_response_id bigint references public.crm_form_submissions(id) on delete set null,
  logged_by text,
  logged_at timestamptz not null default now(),
  updated_by text,
  updated_at timestamptz not null default now()
);
create index if not exists campaign_gifts_slug_idx on public.campaign_gifts (slug);
create index if not exists campaign_gifts_contact_idx on public.campaign_gifts (contact_id);
create unique index if not exists campaign_gifts_response_uq on public.campaign_gifts (source_response_id) where source_response_id is not null;
alter table public.campaign_gifts enable row level security;
drop policy if exists campaign_gifts_read on public.campaign_gifts;
create policy campaign_gifts_read on public.campaign_gifts for select to authenticated using (public.wa_fund_ok());
revoke all on table public.campaign_gifts from anon, authenticated, public;
grant select on table public.campaign_gifts to authenticated;
comment on table public.campaign_gifts is 'wave261 (16/10/26, Steel: an editable gift counter for the Holiday Gift Basket Drive): gifts in kind collected for a campaign, one row a batch (616 books from one donor, 40 toys from a school). Written by staff in the Fundraising app (the drive''s event, Gifts collected) through wa261_gift_save, and by crm_form_apply for a pledge from a form with settings.gift_pledge (status pledged, unconfirmed). Read by staff who can open the Fundraising app (wa_fund_ok); never by anon: the website sees only the total through www_campaign_totals (gifts_in). Money stays in crm_donations.';
comment on column public.campaign_gifts.slug is 'The campaign: a key of app_config donate_campaigns (gift-basket-drive).';
comment on column public.campaign_gifts.quantity is 'How many gifts or items in the batch (a whole number above 0).';
comment on column public.campaign_gifts.what is 'What the batch is, in a few words (Books; Toys, Hygiene essentials).';
comment on column public.campaign_gifts.given_by is 'Who gave it, as the team writes it (a company, a school, a person); staff only.';
comment on column public.campaign_gifts.contact_id is 'The giver in the CRM when known (a pledge from a form sets it).';
comment on column public.campaign_gifts.received_on is 'The day the batch reached us (status received); for a pledge, when it is expected, if known.';
comment on column public.campaign_gifts.status is 'pledged (promised, not in our hands yet) or received (in our hands).';
comment on column public.campaign_gifts.confirmed_at is 'For a pledge: when a staff member confirmed it with the giver. Counted on the website: every received batch and every confirmed pledge; an unconfirmed pledge (from a website form) is not counted until someone presses Confirm.';
comment on column public.campaign_gifts.confirmed_by is 'Who confirmed the pledge (their email).';
comment on column public.campaign_gifts.note is 'Anything the team should remember about the batch (where it is, what to check).';
comment on column public.campaign_gifts.source_response_id is 'The form answer (crm_form_submissions) a pledge came from; one batch an answer.';
comment on column public.campaign_gifts.logged_by is 'Who added the batch (an email, or form:<slug> for a pledge from a form).';
comment on column public.campaign_gifts.logged_at is 'When the batch was added.';
comment on column public.campaign_gifts.updated_by is 'Who last changed it.';
comment on column public.campaign_gifts.updated_at is 'When it last changed.';

-- the seed: the drive's first donation (Amanda, the 15/10/26 Fundraising meeting)
insert into public.campaign_gifts (slug, quantity, what, received_on, status, note, logged_by, updated_by)
select 'gift-basket-drive', 616, 'Books', date '2026-10-15', 'received',
       'First donation of the drive, reported by Amanda at the 15/10/26 meeting; confirm with Amanda', 'Claude (16/10 drive forms)', 'Claude (16/10 drive forms)'
 where not exists (select 1 from public.campaign_gifts where slug = 'gift-basket-drive' and quantity = 616 and what = 'Books');

/* ---------- 3. the Fundraising app's box ---------- */
create or replace function public.wa261_gifts(p_slug text) returns jsonb
language plpgsql stable security definer set search_path to '' as $$
declare v_slug text := lower(btrim(coalesce(p_slug, ''))); v_cfg jsonb; c jsonb; v_rows jsonb; v_counted bigint; v_wait bigint; v_waitn int;
begin
  if not public.wa_fund_ok() then raise exception 'Only people who can open the Fundraising app see the gift count.'; end if;
  begin select value::jsonb into v_cfg from public.app_config where key = 'donate_campaigns'; exception when others then v_cfg := null; end;
  c := case when v_cfg is not null and jsonb_typeof(v_cfg) = 'object' then v_cfg -> v_slug end;
  if c is null or jsonb_typeof(c) <> 'object' then raise exception 'No campaign %', v_slug; end if;
  select coalesce(sum(quantity) filter (where status = 'received' or confirmed_at is not null), 0),
         coalesce(sum(quantity) filter (where status = 'pledged' and confirmed_at is null), 0),
         count(*) filter (where status = 'pledged' and confirmed_at is null)
    into v_counted, v_wait, v_waitn from public.campaign_gifts where slug = v_slug;
  select coalesce(jsonb_agg(to_jsonb(g) order by coalesce(g.received_on, (g.logged_at at time zone 'America/Toronto')::date) desc, g.id desc), '[]'::jsonb)
    into v_rows from public.campaign_gifts g where g.slug = v_slug;
  return jsonb_build_object('slug', v_slug, 'name', c ->> 'name', 'fund_event_id', c -> 'fund_event_id',
    'gift_goal', case when jsonb_typeof(c -> 'gift_goal') = 'number' then c -> 'gift_goal' else 'null'::jsonb end,
    'counted', v_counted, 'waiting', v_wait, 'waiting_n', v_waitn, 'rows', v_rows);
end $$;
comment on function public.wa261_gifts(text) is 'wave261: the Fundraising app''s Gifts collected box for a campaign: the gift goal (app_config donate_campaigns), counted (received plus confirmed pledges, the website''s number), waiting (unconfirmed pledges: quantity and how many) and every batch. Staff who can open the Fundraising app only (wa_fund_ok, checked inside).';
revoke execute on function public.wa261_gifts(text) from public, anon, authenticated;
grant execute on function public.wa261_gifts(text) to authenticated;

create or replace function public.wa261_gift_save(p jsonb) returns jsonb
language plpgsql security definer set search_path to '' as $$
declare
  v_act text := lower(coalesce(p ->> 'action', '')); v_id bigint; v_by text := lower(coalesce(auth.jwt() ->> 'email', ''));
  v_q int; v_st text; v_day date; v_slug text; v_cfg jsonb; o public.campaign_gifts; r public.campaign_gifts; v_conf boolean; v_line text;
begin
  if not public.wa_fund_ok() then raise exception 'Only people who can open the Fundraising app can change the gift count.'; end if;
  if v_by = '' then v_by := 'the Hub'; end if;
  if coalesce(p ->> 'id', '') ~ '^[0-9]+$' then v_id := (p ->> 'id')::bigint; end if;
  if v_act in ('add', 'edit') then
    if coalesce(p ->> 'quantity', '') !~ '^[0-9]{1,7}$' or (p ->> 'quantity')::int <= 0 or (p ->> 'quantity')::int > 1000000 then raise exception 'How many gifts? A whole number above 0.'; end if;
    v_q := (p ->> 'quantity')::int;
    v_st := coalesce(nullif(p ->> 'status', ''), 'received');
    if v_st not in ('pledged', 'received') then raise exception 'The status is received or pledged.'; end if;
    if coalesce(p ->> 'received_on', '') ~ '^\d{4}-\d{2}-\d{2}$' then v_day := (p ->> 'received_on')::date; end if;
    if v_st = 'received' and v_day is null then v_day := (now() at time zone 'America/Toronto')::date; end if;
    v_conf := coalesce((p ->> 'confirmed')::boolean, false);
  end if;
  if v_act = 'add' then
    v_slug := lower(btrim(coalesce(p ->> 'slug', '')));
    begin select value::jsonb into v_cfg from public.app_config where key = 'donate_campaigns'; exception when others then v_cfg := null; end;
    if v_cfg is null or jsonb_typeof(v_cfg) <> 'object' or jsonb_typeof(v_cfg -> v_slug) <> 'object' then raise exception 'No campaign %', v_slug; end if;
    insert into public.campaign_gifts (slug, quantity, what, given_by, received_on, status, confirmed_at, confirmed_by, note, logged_by, updated_by)
    values (v_slug, v_q, nullif(left(btrim(coalesce(p ->> 'what', '')), 300), ''), nullif(left(btrim(coalesce(p ->> 'given_by', '')), 200), ''), v_day, v_st,
            case when v_st = 'pledged' and v_conf then now() end, case when v_st = 'pledged' and v_conf then v_by end,
            nullif(left(btrim(coalesce(p ->> 'note', '')), 2000), ''), v_by, v_by)
    returning * into r;
    v_line := r.quantity || ' ' || coalesce(r.what, 'gifts') || ' (' || r.status || case when r.status = 'pledged' and r.confirmed_at is null then ', waiting to confirm' else '' end || ')';
    insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by) values ('campaign_gift', r.id::text, 'added', null, v_line || ' for ' || r.slug, v_by);
    return to_jsonb(r);
  end if;
  if v_id is null then raise exception 'Which batch?'; end if;
  select * into o from public.campaign_gifts where id = v_id for update;
  if not found then raise exception 'That batch is not there any more.'; end if;
  if v_act = 'edit' then
    update public.campaign_gifts set quantity = v_q, what = nullif(left(btrim(coalesce(p ->> 'what', '')), 300), ''), given_by = nullif(left(btrim(coalesce(p ->> 'given_by', '')), 200), ''),
           received_on = v_day, status = v_st, note = nullif(left(btrim(coalesce(p ->> 'note', '')), 2000), ''),
           confirmed_at = case when v_st = 'received' then confirmed_at when p ? 'confirmed' then case when v_conf then coalesce(confirmed_at, now()) end else confirmed_at end,
           confirmed_by = case when v_st = 'received' then confirmed_by when p ? 'confirmed' then case when v_conf then coalesce(confirmed_by, v_by) end else confirmed_by end,
           updated_by = v_by, updated_at = now()
     where id = v_id returning * into r;
    insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by)
    values ('campaign_gift', r.id::text, 'changed', o.quantity || ' ' || coalesce(o.what, 'gifts') || ' (' || o.status || ')', r.quantity || ' ' || coalesce(r.what, 'gifts') || ' (' || r.status || ')', v_by);
    return to_jsonb(r);
  elsif v_act = 'confirm' then
    if o.status <> 'pledged' then raise exception 'Only a pledge waits for a confirm.'; end if;
    update public.campaign_gifts set confirmed_at = coalesce(confirmed_at, now()), confirmed_by = coalesce(confirmed_by, v_by), updated_by = v_by, updated_at = now() where id = v_id returning * into r;
    insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by) values ('campaign_gift', r.id::text, 'confirmed', null, r.quantity || ' ' || coalesce(r.what, 'gifts') || ' pledged, now counted', v_by);
    return to_jsonb(r);
  elsif v_act = 'receive' then
    update public.campaign_gifts set status = 'received', received_on = coalesce(case when coalesce(p ->> 'received_on', '') ~ '^\d{4}-\d{2}-\d{2}$' then (p ->> 'received_on')::date end, (now() at time zone 'America/Toronto')::date),
           updated_by = v_by, updated_at = now() where id = v_id returning * into r;
    insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by) values ('campaign_gift', r.id::text, 'received', o.status, r.quantity || ' ' || coalesce(r.what, 'gifts') || ' received ' || to_char(r.received_on, 'DD/MM/YY'), v_by);
    return to_jsonb(r);
  elsif v_act = 'remove' then
    execute 'delete from public.campaign_gifts where id = $1' using v_id;
    insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by) values ('campaign_gift', o.id::text, 'removed', o.quantity || ' ' || coalesce(o.what, 'gifts') || ' (' || o.status || ') for ' || o.slug, null, v_by);
    return jsonb_build_object('removed', o.id);
  end if;
  raise exception 'Unknown action %', v_act;
end $$;
comment on function public.wa261_gift_save(jsonb) is 'wave261: the only way staff change campaign_gifts. action add {slug, quantity, what, given_by, received_on, status received|pledged, confirmed, note}, edit {id, same fields}, confirm {id} (a pledge now counts), receive {id, received_on} (a pledge arrived), remove {id}. Staff who can open the Fundraising app only (wa_fund_ok, checked inside); every change has a change_log line (campaign_gift).';
revoke execute on function public.wa261_gift_save(jsonb) from public, anon, authenticated;
grant execute on function public.wa261_gift_save(jsonb) to authenticated;

/* ---------- 4. the public total ---------- */
create or replace function public.www_campaign_totals(p_slug text)
 returns jsonb language plpgsql stable security definer set search_path to '' as $function$
declare
  v_cfg jsonb; c jsonb; v_name text; r record; v_in bigint;
begin
  begin
    select value::jsonb into v_cfg from public.app_config where key = 'donate_campaigns';
  exception when others then v_cfg := null;
  end;
  c := case when v_cfg is not null and jsonb_typeof(v_cfg) = 'object' then v_cfg -> lower(btrim(coalesce(p_slug, ''))) end;
  if c is null or jsonb_typeof(c) <> 'object' or coalesce(c ->> 'name', '') = '' then
    return jsonb_build_object('error', 'not_found');
  end if;
  v_name := c ->> 'name';
  select coalesce(sum(d.amount - coalesce(d.refunded_amount, 0)), 0) as raised,
         count(distinct d.contact_id) + count(*) filter (where d.contact_id is null) as donors,
         count(*) as gifts,
         max(d.donated_at) as last_gift
    into r
    from public.crm_donations d
   where d.campaign = v_name and d.kind in ('donation', 'sponsorship') and d.amount > coalesce(d.refunded_amount, 0);
  -- wave261: the gifts in kind, received or confirmed (an unconfirmed pledge from a form never counts)
  select coalesce(sum(g.quantity), 0) into v_in from public.campaign_gifts g
   where g.slug = lower(btrim(p_slug)) and (g.status = 'received' or g.confirmed_at is not null);
  return jsonb_build_object(
    'slug', lower(btrim(p_slug)), 'name', v_name,
    'raised', round(r.raised, 2), 'donors', r.donors, 'gifts', r.gifts,
    'gifts_in', v_in,
    'goal', case when jsonb_typeof(c -> 'goal') = 'number' then c -> 'goal' else 'null'::jsonb end,
    'gift_goal', case when jsonb_typeof(c -> 'gift_goal') = 'number' then c -> 'gift_goal' else 'null'::jsonb end,
    'open', coalesce((c ->> 'open')::boolean, true),
    'last_gift_at', r.last_gift, 'as_of', now());
end $function$;
comment on function public.www_campaign_totals(text) is '15/10/26 (Holiday Gift Basket Drive page): the public progress of a donation campaign for its page on welfareavenue.com: raised (CAD, gifts of kind donation or sponsorship whose crm_donations.campaign is the campaign''s name in app_config donate_campaigns, less refunds; online gifts and gifts recorded by hand with that campaign alike), donors (distinct contacts), gifts (money gifts), the money goal and the gift goal from the settings, the last gift''s time. wave261 (16/10/26): gifts_in, the gifts in kind collected (campaign_gifts: received batches and confirmed pledges). Aggregates only, never a name or one gift. Anonymous by design (security definer), like www_upcoming.';
revoke execute on function public.www_campaign_totals(text) from public;
grant execute on function public.www_campaign_totals(text) to anon, authenticated;

/* ---------- 5. the Request type ---------- */
insert into public.request_types (key, label, department, description, fields, statuses, default_status, source, enabled, sort, default_assignee, channel, channel_mode)
values ('gift-drive', 'Gift Basket Drive', 'fundraising', 'Someone filled in a Holiday Gift Basket Drive form on the website: a donation of gifts or essentials, a volunteer, a company or sponsor, or a school or group. The details are here; their email and phone are on their CRM contact. Write back, plan the drop-off or the next step, and confirm a pledge in the Fundraising app (the drive''s event, Gifts collected) once it is agreed.',
        '[]'::jsonb, '["Requested", "In progress", "Done"]'::jsonb, 'requested', 'wave261', true, 30, 'Amanda', null, 'brief')
on conflict (key) do nothing;

/* ---------- 5b. crm_form_apply: requests, pledges, the drive's volunteers, reserved test addresses ---------- */
create or replace function public.crm_form_apply(p_submission_id bigint)
 returns jsonb language plpgsql security definer set search_path to '' as $function$
declare
  s record; f record; m jsonb;
  v_em text; v_fn text; v_ln text; v_full text; v_ph text; v_city text; v_src text;
  v_roles text[]; v_tags text[]; v_role text; v_pick text[]; v_consent boolean;
  v_cid bigint; v_created boolean := false; v_vid bigint; v_vcreated boolean := false;
  v_today date := (now() at time zone 'America/Toronto')::date;
  v_roster jsonb := '[]'::jsonb; v_fields jsonb := '[]'::jsonb; v_body text; v_result jsonb;
  fk text; fid bigint; ev record; rid bigint;
  v_uid uuid; v_acid bigint; v_own boolean := false;   -- wave194: a signed-in website account
  v_cand bigint; v_pos_id bigint; v_pos_title text; v_app text; v_dup bigint; v_links text[];   -- wave216: an application
  v_test boolean; v_rtext text; v_req jsonb; v_rtype record; v_rid bigint; v_who text; v_cnt text; v_det jsonb; v_rtitle text;   -- wave261
  v_qty int; v_what text; v_gift bigint; v_gnote text;
begin
  select * into s from public.crm_form_submissions where id = p_submission_id for update;
  if not found then raise exception 'no such submission'; end if;
  if s.status in ('processed', 'test') then return s.result; end if;
  select * into f from public.crm_forms where id = s.form_id;
  m := coalesce(s.mapped, '{}'::jsonb);
  v_em := lower(btrim(coalesce(m #>> '{contact,email}', '')));
  if v_em !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'an email address is needed'; end if;
  -- wave261: an address at a reserved test domain (RFC 2606 and 6761: example.com/.org/.net, .test, .example, .invalid)
  -- can never be a real person: it is handled as a test everywhere (no Request, no pledge, no applicant), so a check of
  -- a live page never reaches Slack, the gift count or Applicants received
  v_test := coalesce(s.is_test, false) or v_em ~ '@([a-z0-9-]+\.)*(example\.(com|org|net)|[a-z0-9-]+\.(test|example|invalid))$';
  if v_test and not coalesce(s.is_test, false) then update public.crm_form_submissions set is_test = true where id = s.id; end if;
  v_fn := nullif(btrim(coalesce(m #>> '{contact,first_name}', '')), '');
  v_ln := nullif(btrim(coalesce(m #>> '{contact,last_name}', '')), '');
  v_full := nullif(btrim(concat_ws(' ', v_fn, v_ln)), '');
  v_ph := nullif(btrim(coalesce(m #>> '{contact,phone}', '')), '');
  v_city := nullif(btrim(coalesce(m #>> '{contact,city}', f.settings ->> 'city', '')), '');
  v_roles := coalesce((select array_agg(distinct x) from jsonb_array_elements_text(coalesce(m -> 'roles', '[]'::jsonb)) x), '{}');
  v_tags := coalesce((select array_agg(distinct x) from jsonb_array_elements_text(coalesce(f.settings -> 'tags', '[]'::jsonb)) x), '{}');
  v_consent := coalesce((m ->> 'consent')::boolean, false);
  v_src := 'form:' || f.slug;
  v_role := coalesce((select x from unnest(array['cook', 'driver', 'server', 'dishwasher', 'photographer', 'videographer', 'community_debrief', 'community_talker']) with ordinality t(x, o)
                       where x = any(v_roles) order by o limit 1), 'server');
  -- wave244: two roles picked (the forms allow 2): the roster row waits as 'volunteer' and the coordinator chooses
  v_pick := coalesce((select array_agg(x order by o) from unnest(array['cook', 'driver', 'server', 'dishwasher', 'photographer', 'videographer', 'community_debrief']) with ordinality t(x, o) where x = any(v_roles)), '{}');
  if cardinality(v_pick) > 1 then v_role := 'volunteer'; end if;

  -- 1. wave194: a signed-in website account fills in its own record (form-submit checked the sign-in);
  --    otherwise the contact with this email (never a merged one)
  v_uid := s.auth_user_id;
  if v_uid is not null then v_acid := public.account_link_user(v_uid, s.lang); end if;
  if v_acid is not null then
    v_cid := v_acid; v_own := true;
  else
  select c.id into v_cid from public.crm_contacts c
   where c.merged_into is null
     and (lower(btrim(c.primary_email)) = v_em or exists (select 1 from unnest(c.emails) x where lower(btrim(x)) = v_em))
   order by (lower(btrim(c.primary_email)) = v_em) desc, c.id
   limit 1;
  end if;

  -- 2. MTL volunteering: the volunteer record (its trigger keeps the contact in step)
  if f.kind = 'volunteer' and coalesce((f.settings ->> 'volunteer_record')::boolean, false) then
    if v_cid is not null then select volunteer_id into v_vid from public.crm_contacts where id = v_cid; end if;
    if v_vid is null then
      select vp.id into v_vid from public.volunteer_people vp
       where exists (select 1 from unnest(vp.emails) x where lower(btrim(x)) = v_em) order by vp.id limit 1;
    end if;
    if v_vid is null then
      insert into public.volunteer_people (full_name, emails, phones, roles, needs_review, review_note, last_applied, joined_note, tags)
      values (coalesce(v_full, v_em), array[v_em], case when v_ph is null then '{}'::text[] else array[v_ph] end, v_roles, true,
              'Applied through the Hub form "' || f.title || '" on ' || to_char(v_today, 'DD Mon YYYY'), v_today, 'Hub form: ' || f.title, v_tags)
      returning id into v_vid;
      v_vcreated := true;
    else
      update public.volunteer_people vp set
        roles = (select coalesce(array_agg(distinct x), '{}') from unnest(coalesce(vp.roles, '{}') || v_roles) x),
        emails = case when exists (select 1 from unnest(vp.emails) x where lower(btrim(x)) = v_em) then vp.emails else coalesce(vp.emails, '{}') || v_em end,
        phones = case when v_ph is not null and cardinality(coalesce(vp.phones, '{}')) = 0 then array[v_ph] else vp.phones end,
        tags = (select coalesce(array_agg(distinct x), '{}') from unnest(coalesce(vp.tags, '{}') || v_tags) x),
        last_applied = v_today
      where vp.id = v_vid;
    end if;
    if v_cid is null then
      select id into v_cid from public.crm_contacts where volunteer_id = v_vid and merged_into is null order by id limit 1;
      v_created := v_cid is not null and v_vcreated;
    end if;
  end if;

  -- 3. a new contact, or 4. fill in what the contact is missing (never erase what the team entered)
  if v_cid is null then
    insert into public.crm_contacts (full_name, first_name, last_name, emails, phones, city, province, postal_code, address, language, kinds, tags, source, created_by, updated_by)
    values (coalesce(v_full, v_em), v_fn, v_ln, array[v_em], case when v_ph is null then '{}'::text[] else array[v_ph] end, v_city,
            nullif(btrim(coalesce(m #>> '{contact,province}', '')), ''), nullif(btrim(coalesce(m #>> '{contact,postal_code}', '')), ''),
            nullif(btrim(coalesce(m #>> '{contact,address}', '')), ''), nullif(btrim(coalesce(m #>> '{contact,language}', '')), ''),
            array[case when f.kind = 'volunteer' then 'volunteer' else 'supporter' end], v_tags, 'hub_form', v_src, v_src)
    returning id into v_cid;
    v_created := true;
  else
    update public.crm_contacts c set
      first_name = case when v_own then coalesce(v_fn, c.first_name) else coalesce(nullif(c.first_name, ''), v_fn) end,
      last_name = case when v_own then coalesce(v_ln, c.last_name) else coalesce(nullif(c.last_name, ''), v_ln) end,
      full_name = case when v_own and (v_fn is not null or v_ln is not null) then btrim(concat_ws(' ', coalesce(v_fn, c.first_name), coalesce(v_ln, c.last_name)))
                       when coalesce(c.full_name, '') in ('', '(no name)') or lower(c.full_name) = v_em then coalesce(v_full, c.full_name) else c.full_name end,
      emails = case when exists (select 1 from unnest(c.emails) x where lower(btrim(x)) = v_em) then c.emails else coalesce(c.emails, '{}') || v_em end,
      phones = case when v_own and v_ph is not null then array[v_ph] || array_remove(coalesce(c.phones, '{}'), v_ph)
                    when v_ph is not null and cardinality(coalesce(c.phones, '{}')) = 0 then array[v_ph] else c.phones end,
      city = case when v_own then coalesce(nullif(btrim(coalesce(m #>> '{contact,city}', '')), ''), c.city) else coalesce(nullif(c.city, ''), v_city) end,
      province = case when v_own then coalesce(nullif(btrim(coalesce(m #>> '{contact,province}', '')), ''), c.province)
                      else coalesce(nullif(c.province, ''), nullif(btrim(coalesce(m #>> '{contact,province}', '')), '')) end,
      postal_code = case when v_own then coalesce(nullif(upper(btrim(coalesce(m #>> '{contact,postal_code}', ''))), ''), c.postal_code)
                         else coalesce(nullif(c.postal_code, ''), nullif(btrim(coalesce(m #>> '{contact,postal_code}', '')), '')) end,
      address = case when v_own then coalesce(nullif(btrim(coalesce(m #>> '{contact,address}', '')), ''), c.address)
                     else coalesce(nullif(c.address, ''), nullif(btrim(coalesce(m #>> '{contact,address}', '')), '')) end,
      language = case when v_own then coalesce(nullif(btrim(coalesce(m #>> '{contact,language}', '')), ''), c.language)
                      else coalesce(nullif(c.language, ''), nullif(btrim(coalesce(m #>> '{contact,language}', '')), '')) end,
      kinds = case when f.kind = 'volunteer' and not ('volunteer' = any(coalesce(c.kinds, '{}'))) then coalesce(c.kinds, '{}') || array['volunteer']
                   when f.kind <> 'volunteer' and cardinality(coalesce(c.kinds, '{}')) = 0 then array['supporter'] else c.kinds end,
      tags = (select coalesce(array_agg(x order by x), '{}') from (select distinct x from unnest(coalesce(c.tags, '{}') || v_tags) x) t),
      source = case when v_created then 'hub_form' else c.source end,
      created_by = case when v_created then v_src else c.created_by end,
      updated_by = v_src
    where c.id = v_cid;
  end if;

  -- 5. the email permission: a ticked box is express consent, recorded with the form's name and the day. Someone who
  --    unsubscribed stays unsubscribed (the box could have been ticked by anyone who typed their address); the
  --    timeline entry shows the tick, and the team confirms with them before changing anything.
  if v_consent and (v_created or v_own or coalesce((select email_status from public.crm_contacts where id = v_cid), '') <> 'unsubscribed') then
    update public.crm_contacts set email_consent = 'express',
      consent_source = 'Hub form: ' || f.title || ' (' || to_char(v_today, 'DD Mon YYYY') || ')', consent_at = now(),
      email_status = case when email_status in ('bounced', 'complained') then email_status else 'subscribed' end
    where id = v_cid;
  end if;

  -- 6. custom fields: the latest answer wins
  for fk in select jsonb_object_keys(coalesce(m -> 'fields', '{}'::jsonb)) loop
    select id into fid from public.crm_fields where key = fk and archived_at is null;
    if fid is null then continue; end if;
    insert into public.crm_contact_fields (contact_id, field_id, value, source, updated_at, updated_by)
    values (v_cid, fid, m -> 'fields' -> fk, v_src, now(), v_src)
    on conflict (contact_id, field_id) do update set value = excluded.value, source = excluded.source, updated_at = now(), updated_by = excluded.updated_by;
    v_fields := v_fields || to_jsonb(fk);
  end loop;

  -- 7. the dates they picked: a sign-up on each event's roster, to be confirmed by the team (status TBD)
  if v_vid is not null then
    for ev in select e.id, e.event_date from public.volunteer_events e
               where e.id in (select x::bigint from jsonb_array_elements_text(coalesce(m -> 'dates', '[]'::jsonb)) x where x ~ '^[0-9]+$')
                 and e.status = 'planned' and e.event_date >= v_today
               order by e.event_date loop
      if exists (select 1 from public.event_roster r where r.event_id = ev.id and r.person_id = v_vid) then
        v_roster := v_roster || jsonb_build_object('event_id', ev.id, 'date', ev.event_date, 'already', true);
        continue;
      end if;
      insert into public.event_roster (event_id, person_id, person_name, role, status, notes, detail)
      values (ev.id, v_vid, coalesce(v_full, v_em), v_role, 'TBD',
              'Signed up through the Hub form "' || f.title || '" on ' || to_char(v_today, 'DD Mon YYYY'),
              jsonb_build_object('source', 'hub_form', 'form', f.slug, 'submission_id', s.id) || case when v_role = 'volunteer' and cardinality(v_pick) > 1 then jsonb_build_object('role_choices', to_jsonb(v_pick)) else '{}'::jsonb end)
      returning id into rid;
      v_roster := v_roster || jsonb_build_object('event_id', ev.id, 'date', ev.event_date, 'roster_id', rid, 'role', v_role);
    end loop;
  end if;

  -- 7b. wave216: an application form puts the person on the Applications board (HR centre) as a New card, with the
  --     role they picked, their CV (hub-mail, read later by recruit-actions cv_scan), links and why. A second application
  --     for the same role in 90 days adds to the open card instead. A test submission is a practice card (Clear practice).
  if f.kind = 'application' then
    v_app := coalesce(m #>> '{application,position}', '');
    if v_app ~ '^p:[0-9]+$' then select p.id, p.title into v_pos_id, v_pos_title from public.hub_positions p where p.id = substr(v_app, 3)::bigint; end if;
    v_links := coalesce((select array_agg(btrim(x)) from jsonb_array_elements_text(coalesce(m #> '{application,links}', '[]'::jsonb)) x where btrim(x) <> ''), '{}');
    if not v_test then
      select c.id into v_dup from public.hub_candidates c
       where lower(c.email) = v_em and not coalesce(c.practice, false) and c.created_at > now() - interval '90 days'
         and coalesce(c.status, 'new') not in ('declined', 'withdrawn') and c.position_id is not distinct from v_pos_id
       order by c.created_at desc limit 1;
    end if;
    if v_dup is not null then
      update public.hub_candidates c set
        notes = btrim(coalesce(c.notes, '') || E'\n' || 'Applied again on the website ("' || f.title || '", ' || to_char(v_today, 'DD Mon YYYY') || ').'),
        cv_path = coalesce(m #>> '{application,cv,path}', c.cv_path), cv_name = coalesce(m #>> '{application,cv,name}', c.cv_name),
        cv_read_at = case when m #>> '{application,cv,path}' is not null then null else c.cv_read_at end,
        links = (select coalesce(array_agg(distinct x), '{}') from unnest(coalesce(c.links, '{}') || v_links) x),
        phone = coalesce(nullif(c.phone, ''), v_ph), updated_at = now(), updated_by = v_src
       where c.id = v_dup;
      v_cand := v_dup;
    else
      insert into public.hub_candidates (name, email, phone, role, position_id, source, summary, links, cv_path, cv_name, status, stage_at, created_at, notes, updated_at, updated_by, practice)
      values (left(coalesce(v_full, v_em), 120), v_em, v_ph, coalesce(v_pos_title, case when f.lang = 'fr' then 'Candidature générale' else 'General application' end), v_pos_id, 'website',
              nullif(left(coalesce(m #>> '{application,why}', ''), 4000), ''), v_links, m #>> '{application,cv,path}', m #>> '{application,cv,name}',
              'new', now(), s.created_at, 'Applied on the website ("' || f.title || '", ' || to_char(v_today, 'DD Mon YYYY') || ').' || coalesce(E'\n' || coalesce((select q ->> 'label' from jsonb_array_elements(f.questions) q where q ->> 'to' = 'note' limit 1) || ': ', '') || nullif(m ->> 'note', ''), ''),
              now(), v_src, v_test)
      returning id into v_cand;
      insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by)
      values ('candidate', v_cand::text, 'added', null, coalesce(v_full, v_em) || ' for ' || coalesce(v_pos_title, 'a general application') || ' (website form ' || f.slug || case when v_test then ', test' else '' end || ')', v_src);
    end if;
  end if;

  -- 7c. wave239: a volunteer form that keeps a volunteering record also files the application in Applicants received
  --     (wa209_volunteer_apply: the application, its timeline line, the person tagged "volunteer applicant"), so the
  --     Volunteer Manager sees every applicant in one place. Not for a test, and not twice in a week for one person.
  --     wave261: a form outside the servings (the Holiday Gift Basket Drive) names what they applied for with
  --     settings.role_text and the choices of the question settings.role_q ("Holiday Gift Basket Drive: Wrapping gifts").
  if f.kind = 'volunteer' and coalesce((f.settings ->> 'volunteer_record')::boolean, false) and not v_test
     and not exists (select 1 from public.volunteer_applications a where lower(coalesce(a.email, '')) = v_em and a.applied_at > s.created_at - interval '7 days') then
    v_rtext := nullif(btrim(coalesce(f.settings ->> 'role_text', '')), '');
    if v_rtext is not null and coalesce(f.settings ->> 'role_q', '') <> '' then
      v_rtext := v_rtext || coalesce(': ' || (select string_agg(coalesce(o ->> 'l', x), ', ' order by ord)
                   from jsonb_array_elements_text(case when jsonb_typeof(s.answers -> (f.settings ->> 'role_q')) = 'array' then s.answers -> (f.settings ->> 'role_q') else '[]'::jsonb end) with ordinality t(x, ord)
                   left join lateral (select o from jsonb_array_elements(coalesce((select q -> 'options' from jsonb_array_elements(f.questions) q where q ->> 'id' = f.settings ->> 'role_q' limit 1), '[]'::jsonb)) o where o ->> 'v' = x limit 1) oo on true), '');
    end if;
    begin
      perform public.wa209_volunteer_apply(jsonb_build_object(
        'name', coalesce(v_full, v_em), 'email', v_em, 'phone', v_ph, 'roles', to_jsonb(v_roles),
        'role_text', coalesce(v_rtext, array_to_string((select array_agg(public.wa171_role_label(x, 'en') order by o) from unnest(v_roles) with ordinality t(x, o)), ', ')),
        'source', 'website', 'source_ref', 'form:' || s.id, 'applied_at', s.created_at, 'message', nullif(m ->> 'note', ''),
        'language', coalesce(f.lang, 'en'), 'by', v_src));
    exception when others then
      insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by)
      values ('form_submission', s.id::text, 'applicant', null, 'Applicants received: ' || left(sqlerrm, 300), v_src);
    end;
  end if;

  -- 7d. wave261: a pledge of gifts in kind (settings.gift_pledge, the campaign in settings.campaign): a pledged
  --     campaign_gifts row that waits for a staff Confirm (an unconfirmed pledge is never counted on the website)
  if coalesce((f.settings ->> 'gift_pledge')::boolean, false) and coalesce(f.settings ->> 'campaign', '') ~ '^[a-z0-9][a-z0-9-]{0,39}$' and not v_test then
    v_qty := case when coalesce(s.answers ->> 'how_many', '') ~ '^[0-9]{1,7}(\.[0-9]+)?$' then round((s.answers ->> 'how_many')::numeric)::int end;
    if v_qty is not null and v_qty > 0 and v_qty <= 1000000 then
      v_what := nullif(concat_ws(', ', (select string_agg(coalesce(o ->> 'l', x), ', ' order by ord)
                   from jsonb_array_elements_text(case when jsonb_typeof(s.answers -> 'what') = 'array' then s.answers -> 'what' else '[]'::jsonb end) with ordinality t(x, ord)
                   left join lateral (select o from jsonb_array_elements(coalesce((select q -> 'options' from jsonb_array_elements(f.questions) q where q ->> 'id' = 'what' limit 1), '[]'::jsonb)) o where o ->> 'v' = x limit 1) oo on true),
                 nullif(btrim(coalesce(s.answers ->> 'what_other', '')), '')), '');
      v_gnote := 'Pledged on the website form "' || f.title || '" on ' || to_char(v_today, 'DD/MM/YY') || '.'
        || coalesce(' ' || (select d ->> 'label' || ': ' || (d ->> 'value') from jsonb_array_elements(coalesce(s.display, '[]'::jsonb)) d
                             where d ->> 'label' = (select q ->> 'label' from jsonb_array_elements(f.questions) q where q ->> 'id' = 'dropoff' limit 1) limit 1) || '.', '')
        || coalesce(' Area: ' || nullif(btrim(coalesce(s.answers ->> 'area', '')), '') || '.', '')
        || coalesce(' Ready: ' || nullif(btrim(coalesce(s.answers ->> 'when', '')), '') || '.', '');
      insert into public.campaign_gifts (slug, quantity, what, given_by, contact_id, status, note, source_response_id, logged_by, updated_by)
      values (f.settings ->> 'campaign', v_qty, left(v_what, 300), left(coalesce(nullif(btrim(coalesce(s.answers ->> 'organization', '')), ''), v_full, v_em), 200), v_cid, 'pledged', left(v_gnote, 2000), s.id, v_src, v_src)
      on conflict do nothing
      returning id into v_gift;
      if v_gift is not null then
        insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by)
        values ('campaign_gift', v_gift::text, 'added', null, v_qty || ' ' || coalesce(v_what, 'gifts') || ' (pledged on the website, waiting to confirm) for ' || (f.settings ->> 'campaign'), v_src);
      end if;
    end if;
  end if;

  -- 7e. wave261: settings.request files a Request for the team (request_types: department, assignee), announced the way
  --     every new Request is; the details leave out the email and the phone (they are on the CRM contact)
  v_req := case when jsonb_typeof(f.settings -> 'request') = 'object' then f.settings -> 'request' end;
  if v_req is not null and not v_test then
    select * into v_rtype from public.request_types where key = v_req ->> 'type' and enabled;
    if found then
      v_who := coalesce(nullif(btrim(coalesce(s.answers ->> (v_req ->> 'who'), '')), ''), v_fn, v_full, split_part(v_em, '@', 1));
      v_cnt := case when coalesce(v_req ->> 'count', '') <> '' and coalesce(s.answers ->> (v_req ->> 'count'), '') ~ '^[0-9]{1,7}(\.[0-9]+)?$'
                    then round((s.answers ->> (v_req ->> 'count'))::numeric)::text || ' ' || coalesce(nullif(v_req ->> 'count_word', ''), '') end;
      v_rtitle := left(coalesce(nullif(v_req ->> 'title', ''), f.title) || ': ' || v_who || coalesce(' (' || btrim(v_cnt) || ')', ''), 200);
      select coalesce(jsonb_object_agg(k, val), '{}'::jsonb) into v_det from (
        select left(d ->> 'label', 80) as k, left(coalesce(d ->> 'value', ''), 500) as val
          from jsonb_array_elements(coalesce(s.display, '[]'::jsonb)) with ordinality t(d, ord)
         where d ->> 'label' not in (select q ->> 'label' from jsonb_array_elements(f.questions) q where q ->> 'to' in ('contact.email', 'contact.phone') or q ->> 'type' in ('email', 'phone'))
           and d ->> 'label' not in ('Email permission', 'Permission courriel')
           and d ->> 'label' not in (select q ->> 'label' from jsonb_array_elements(f.questions) q where q ->> 'id' = 'rule_ok')
         order by ord) x;
      v_det := v_det || jsonb_build_object('Form', f.title, 'In the CRM', 'Contact ' || v_cid || ' (email and phone there)');
      insert into public.dept_requests (type_key, department, title, details, status, requested_by, requested_email, source, assignee)
      values (v_rtype.key, v_rtype.department, v_rtitle, v_det, coalesce(v_rtype.default_status, 'requested'), left(coalesce(v_full, v_em), 120) || ' (website)', null, v_src, v_rtype.default_assignee)
      returning id into v_rid;
    end if;
  end if;

  -- 8. the timeline
  select string_agg(coalesce(d ->> 'label', '') || ': ' || coalesce(d ->> 'value', ''), E'\n' order by o) into v_body
    from jsonb_array_elements(coalesce(s.display, '[]'::jsonb)) with ordinality t(d, o);
  insert into public.crm_interactions (contact_id, kind, direction, channel, subject, body, occurred_at, source, source_ref, meta, created_by)
  values (v_cid, 'form', 'in', 'web', 'Filled in "' || f.title || '"' || case when v_test then ' (test)' else '' end, v_body, s.created_at, 'hub_form', 'form:' || s.id,
          jsonb_build_object('form_id', f.id, 'slug', f.slug, 'submission_id', s.id, 'consent', v_consent, 'is_test', v_test, 'account', v_own), v_src);
  update public.crm_contacts set last_activity_at = greatest(coalesce(last_activity_at, s.created_at), s.created_at) where id = v_cid;

  v_result := jsonb_build_object('contact_id', v_cid, 'created', v_created, 'volunteer_id', v_vid, 'volunteer_created', v_vcreated,
                                 'candidate_id', v_cand, 'roster', v_roster, 'fields', v_fields, 'consent', v_consent, 'account', v_own,
                                 'gift_id', v_gift, 'request_id', v_rid, 'test', v_test);
  update public.crm_form_submissions set contact_id = v_cid, status = case when v_test then 'test' else 'processed' end,
         processed_at = now(), result = v_result, error = null
   where id = s.id;
  return v_result;
end $function$;
comment on function public.crm_form_apply(bigint) is 'Applies one form submission (wave156): the contact, the MTL volunteering record, roster sign-ups, custom fields, the consent and a timeline entry, in one transaction. wave194: a submission from a signed-in website account (auth_user_id) uses that account''s own record and saves what they typed to it (names, phone first, address, city, province, postal code, language); its ticked permission box counts even after an unsubscribe. Anyone else''s submission only fills gaps and never re-subscribes. wave216: an application form adds a card to the Applications board; wave239: a volunteer form with a volunteering record files the application in Applicants received. wave261 (16/10/26): settings.request files a Request (request_types, assigned to its default assignee) without the email or phone; settings.gift_pledge adds a pledged campaign_gifts row waiting for a Confirm; settings.role_text names what a volunteer applied for; an address at a reserved test domain (example.com/.org/.net, .test, .example, .invalid) is a test (no Request, pledge or applicant; the submission is marked is_test). Called by form-submit with the service role.';
revoke execute on function public.crm_form_apply(bigint) from public, anon, authenticated;

/* ---------- 6. the eight forms (build/data/wa261_forms.py), live ---------- */
insert into public.crm_forms (slug, title, intro, lang, kind, status, questions, consent, thank_you, settings, cover_photo_id, purpose, created_by, updated_by, published_at, published_by)
select $j$gift-drive-give$j$, $j$Donate gifts and essentials$j$, $j$Thank you for thinking of our Holiday Gift Basket Drive! Tell us what you’d like to give and we’ll write back to plan the drop-off, or a pick-up together.$j$, $j$en$j$, $j$general$j$, 'published', $j$[{"id": "first_name", "type": "text", "label": "First name", "required": true, "to": "contact.first_name"}, {"id": "last_name", "type": "text", "label": "Last name", "required": true, "to": "contact.last_name"}, {"id": "email", "type": "email", "label": "Email", "required": true, "to": "contact.email"}, {"id": "phone", "type": "phone", "label": "Phone", "required": false, "to": "contact.phone", "help": "Only if you’d like us to call or text about the drop-off."}, {"id": "organization", "type": "text", "label": "Company or organization", "required": false, "help": "If you’re giving on behalf of a company, a school or a group."}, {"id": "what", "type": "multi", "label": "What would you like to give?", "required": true, "help": "Clothing can be gently used. Hygiene essentials and toys must be brand new, so every gift feels like a gift.", "options": [{"v": "clothing", "l": "Clothing (gently used is fine)"}, {"v": "hygiene", "l": "Hygiene essentials (brand new)"}, {"v": "toys", "l": "Toys (brand new)"}, {"v": "books", "l": "Books"}, {"v": "other", "l": "Something else"}]}, {"id": "what_other", "type": "text", "label": "Something else? Tell us what", "required": false}, {"id": "how_many", "type": "number", "label": "Roughly how many items?", "required": true, "help": "An estimate is perfect."}, {"id": "dropoff", "type": "choice", "label": "How would you like to get them to us?", "required": true, "options": [{"v": "dropoff", "l": "I’ll drop them off"}, {"v": "pickup", "l": "I’d need a pick-up"}, {"v": "not_sure", "l": "Not sure yet"}]}, {"id": "area", "type": "text", "label": "Your area or postal code", "required": false, "help": "So we can plan a drop-off spot or a pick-up near you."}, {"id": "when", "type": "text", "label": "When will your items be ready?", "required": false, "help": "We’re collecting donations from mid-November to the end of November."}, {"id": "comments", "type": "long_text", "label": "Anything else we should know?", "required": false, "to": "note"}, {"id": "rule_ok", "type": "multi", "label": "Before you send", "required": true, "options": [{"v": "yes", "l": "I understand that hygiene essentials and toys must be brand new."}]}]$j$::jsonb, $j${"ask": true, "required": false, "label": "Yes, Welfare Avenue can email me news, volunteer call-outs and ways to help. I can unsubscribe at any time."}$j$::jsonb, $j$Your gifts will make someone’s holidays a little brighter. Our team will write to you soon about the drop-off or a pick-up.$j$, $j${"tags": ["gift-basket-drive"], "campaign": "gift-basket-drive", "gift_pledge": true, "confirm": false, "request": {"type": "gift-drive", "title": "Gift drive, items", "who": "organization", "count": "how_many", "count_word": "items"}}$j$::jsonb, 110, $j$gifts$j$, 'Claude (16/10 drive forms)', 'Claude (16/10 drive forms)', now(), 'Claude for Steel (16/10/26: "pop up a form for each of those actions")'
 where not exists (select 1 from public.crm_forms where slug = $j$gift-drive-give$j$);
insert into public.crm_forms (slug, title, intro, lang, kind, status, questions, consent, thank_you, settings, cover_photo_id, purpose, created_by, updated_by, published_at, published_by)
select $j$paniers-donner$j$, $j$Donner des cadeaux et des articles$j$, $j$Merci de penser à notre collecte de paniers-cadeaux des Fêtes! Dites-nous ce que vous aimeriez donner et nous vous écrirons pour planifier le dépôt, ou une cueillette ensemble.$j$, $j$fr$j$, $j$general$j$, 'published', $j$[{"id": "first_name", "type": "text", "label": "Prénom", "required": true, "to": "contact.first_name"}, {"id": "last_name", "type": "text", "label": "Nom", "required": true, "to": "contact.last_name"}, {"id": "email", "type": "email", "label": "Courriel", "required": true, "to": "contact.email"}, {"id": "phone", "type": "phone", "label": "Téléphone", "required": false, "to": "contact.phone", "help": "Seulement si vous voulez qu’on vous appelle ou vous texte pour le dépôt."}, {"id": "organization", "type": "text", "label": "Entreprise ou organisme", "required": false, "help": "Si vous donnez au nom d’une entreprise, d’une école ou d’un groupe."}, {"id": "what", "type": "multi", "label": "Qu’aimeriez-vous donner?", "required": true, "help": "Les vêtements peuvent être usagés, en bon état. Les articles d’hygiène et les jouets doivent être neufs, pour que chaque cadeau en soit vraiment un.", "options": [{"v": "clothing", "l": "Vêtements (usagés en bon état, c’est parfait)"}, {"v": "hygiene", "l": "Articles d’hygiène (neufs)"}, {"v": "toys", "l": "Jouets (neufs)"}, {"v": "books", "l": "Livres"}, {"v": "other", "l": "Autre chose"}]}, {"id": "what_other", "type": "text", "label": "Autre chose? Dites-nous quoi", "required": false}, {"id": "how_many", "type": "number", "label": "Environ combien d’articles?", "required": true, "help": "Une estimation, c’est parfait."}, {"id": "dropoff", "type": "choice", "label": "Comment aimeriez-vous nous les remettre?", "required": true, "options": [{"v": "dropoff", "l": "Je vais les déposer"}, {"v": "pickup", "l": "J’aurais besoin d’une cueillette"}, {"v": "not_sure", "l": "Je ne sais pas encore"}]}, {"id": "area", "type": "text", "label": "Votre quartier ou code postal", "required": false, "help": "Pour planifier un lieu de dépôt ou une cueillette près de chez vous."}, {"id": "when", "type": "text", "label": "Quand vos articles seront-ils prêts?", "required": false, "help": "Nous recueillons les dons de la mi-novembre à la fin novembre."}, {"id": "comments", "type": "long_text", "label": "Autre chose que nous devrions savoir?", "required": false, "to": "note"}, {"id": "rule_ok", "type": "multi", "label": "Avant d’envoyer", "required": true, "options": [{"v": "yes", "l": "Je comprends que les articles d’hygiène et les jouets doivent être neufs."}]}]$j$::jsonb, $j${"ask": true, "required": false, "label": "Oui, Welfare Avenue peut m’envoyer par courriel des nouvelles, des appels aux bénévoles et des façons d’aider. Je peux me désabonner en tout temps."}$j$::jsonb, $j$Vos cadeaux vont rendre les Fêtes de quelqu’un un peu plus belles. Notre équipe vous écrira bientôt pour le dépôt ou la cueillette.$j$, $j${"tags": ["gift-basket-drive"], "campaign": "gift-basket-drive", "gift_pledge": true, "confirm": false, "request": {"type": "gift-drive", "title": "Gift drive, items", "who": "organization", "count": "how_many", "count_word": "items"}}$j$::jsonb, 110, $j$gifts$j$, 'Claude (16/10 drive forms)', 'Claude (16/10 drive forms)', now(), 'Claude for Steel (16/10/26: "pop up a form for each of those actions")'
 where not exists (select 1 from public.crm_forms where slug = $j$paniers-donner$j$);
insert into public.crm_forms (slug, title, intro, lang, kind, status, questions, consent, thank_you, settings, cover_photo_id, purpose, created_by, updated_by, published_at, published_by)
select $j$gift-drive-volunteer$j$, $j$Volunteer with the drive$j$, $j$Help us sort, wrap and deliver 6,000 gifts this holiday season. Tell us how you’d like to help and when you’re free, and we’ll be in touch as soon as the dates are set.$j$, $j$en$j$, $j$volunteer$j$, 'published', $j$[{"id": "first_name", "type": "text", "label": "First name", "required": true, "to": "contact.first_name"}, {"id": "last_name", "type": "text", "label": "Last name", "required": true, "to": "contact.last_name"}, {"id": "email", "type": "email", "label": "Email", "required": true, "to": "contact.email"}, {"id": "phone", "type": "phone", "label": "Phone", "required": true, "to": "contact.phone", "help": "So we can reach you about the dates."}, {"id": "tasks", "type": "multi", "label": "How would you like to help?", "required": true, "options": [{"v": "wrapping", "l": "Wrapping gifts at our December event", "d": "One or two weekends in December. Dates are coming soon."}, {"v": "sorting", "l": "Collecting and sorting donations", "d": "From mid-November to the end of November."}, {"v": "delivery", "l": "Delivering gifts", "d": "Before the holidays, across Montreal."}]}, {"id": "availability", "type": "multi", "label": "When are you usually free?", "required": true, "options": [{"v": "weekday_day", "l": "Weekdays, daytime"}, {"v": "weekday_evening", "l": "Weekday evenings"}, {"v": "weekend", "l": "Weekends"}]}, {"id": "age_16", "type": "yes_no", "label": "Are you 16 or older?", "required": true, "to": "field:age_16_plus", "help": "If not, tell us below and we’ll figure out together how you can join in."}, {"id": "heard", "type": "text", "label": "How did you hear about the drive?", "required": false}, {"id": "comments", "type": "long_text", "label": "Anything else we should know?", "required": false, "to": "note"}]$j$::jsonb, $j${"ask": true, "required": false, "label": "Yes, Welfare Avenue can email me news, volunteer call-outs and ways to help. I can unsubscribe at any time."}$j$::jsonb, $j$You’re signed up to help with the Holiday Gift Basket Drive. We’ll be in touch as soon as the dates are set.$j$, $j${"tags": ["gift-basket-drive"], "campaign": "gift-basket-drive", "volunteer_record": true, "city": "Montreal", "confirm": false, "role_text": "Holiday Gift Basket Drive", "role_q": "tasks", "request": {"type": "gift-drive", "title": "Gift drive, volunteer"}}$j$::jsonb, 102, $j$volunteers$j$, 'Claude (16/10 drive forms)', 'Claude (16/10 drive forms)', now(), 'Claude for Steel (16/10/26: "pop up a form for each of those actions")'
 where not exists (select 1 from public.crm_forms where slug = $j$gift-drive-volunteer$j$);
insert into public.crm_forms (slug, title, intro, lang, kind, status, questions, consent, thank_you, settings, cover_photo_id, purpose, created_by, updated_by, published_at, published_by)
select $j$paniers-benevole$j$, $j$Faire du bénévolat pour la collecte$j$, $j$Aidez-nous à trier, emballer et livrer 6 000 cadeaux cet hiver. Dites-nous comment vous aimeriez aider et quand vous êtes disponible; nous vous écrirons dès que les dates seront fixées.$j$, $j$fr$j$, $j$volunteer$j$, 'published', $j$[{"id": "first_name", "type": "text", "label": "Prénom", "required": true, "to": "contact.first_name"}, {"id": "last_name", "type": "text", "label": "Nom", "required": true, "to": "contact.last_name"}, {"id": "email", "type": "email", "label": "Courriel", "required": true, "to": "contact.email"}, {"id": "phone", "type": "phone", "label": "Téléphone", "required": true, "to": "contact.phone", "help": "Pour vous joindre au sujet des dates."}, {"id": "tasks", "type": "multi", "label": "Comment aimeriez-vous aider?", "required": true, "options": [{"v": "wrapping", "l": "Emballer des cadeaux à notre événement de décembre", "d": "Une ou deux fins de semaine en décembre. Les dates seront annoncées bientôt."}, {"v": "sorting", "l": "Recueillir et trier les dons", "d": "De la mi-novembre à la fin novembre."}, {"v": "delivery", "l": "Livrer des cadeaux", "d": "Avant les Fêtes, partout à Montréal."}]}, {"id": "availability", "type": "multi", "label": "Quand êtes-vous habituellement disponible?", "required": true, "options": [{"v": "weekday_day", "l": "En semaine, le jour"}, {"v": "weekday_evening", "l": "En semaine, le soir"}, {"v": "weekend", "l": "La fin de semaine"}]}, {"id": "age_16", "type": "yes_no", "label": "Avez-vous 16 ans ou plus?", "required": true, "to": "field:age_16_plus", "help": "Sinon, dites-le-nous plus bas et nous verrons ensemble comment vous pouvez participer."}, {"id": "heard", "type": "text", "label": "Comment avez-vous entendu parler de la collecte?", "required": false}, {"id": "comments", "type": "long_text", "label": "Autre chose que nous devrions savoir?", "required": false, "to": "note"}]$j$::jsonb, $j${"ask": true, "required": false, "label": "Oui, Welfare Avenue peut m’envoyer par courriel des nouvelles, des appels aux bénévoles et des façons d’aider. Je peux me désabonner en tout temps."}$j$::jsonb, $j$Nous avons bien reçu votre inscription pour aider à la collecte de paniers-cadeaux des Fêtes. Nous vous écrirons dès que les dates seront fixées.$j$, $j${"tags": ["gift-basket-drive"], "campaign": "gift-basket-drive", "volunteer_record": true, "city": "Montreal", "confirm": false, "role_text": "Holiday Gift Basket Drive", "role_q": "tasks", "request": {"type": "gift-drive", "title": "Gift drive, volunteer"}}$j$::jsonb, 102, $j$volunteers$j$, 'Claude (16/10 drive forms)', 'Claude (16/10 drive forms)', now(), 'Claude for Steel (16/10/26: "pop up a form for each of those actions")'
 where not exists (select 1 from public.crm_forms where slug = $j$paniers-benevole$j$);
insert into public.crm_forms (slug, title, intro, lang, kind, status, questions, consent, thank_you, settings, cover_photo_id, purpose, created_by, updated_by, published_at, published_by)
select $j$gift-drive-sponsor$j$, $j$Companies and sponsors$j$, $j$Businesses make the drive possible, with products, wrapping supplies, a collection bin or a team that wraps with us. Tell us a little about your company and we’ll send you our sponsorship package.$j$, $j$en$j$, $j$general$j$, 'published', $j$[{"id": "company", "type": "text", "label": "Company or organization", "required": true}, {"id": "first_name", "type": "text", "label": "Your first name", "required": true, "to": "contact.first_name"}, {"id": "last_name", "type": "text", "label": "Your last name", "required": true, "to": "contact.last_name"}, {"id": "email", "type": "email", "label": "Email", "required": true, "to": "contact.email"}, {"id": "role", "type": "text", "label": "Your role", "required": false}, {"id": "phone", "type": "phone", "label": "Phone", "required": false, "to": "contact.phone"}, {"id": "help_how", "type": "multi", "label": "How would you like to help?", "required": true, "options": [{"v": "products", "l": "Donating products (in kind)"}, {"v": "supplies", "l": "Wrapping supplies"}, {"v": "team", "l": "Employee volunteering (wrap with us)"}, {"v": "bin", "l": "A collection bin at your location"}, {"v": "money", "l": "A financial sponsorship"}]}, {"id": "size", "type": "text", "label": "What size of support do you have in mind?", "required": false, "help": "A number of items, a budget or a team size: anything helps us plan."}, {"id": "message", "type": "long_text", "label": "Your message", "required": false, "to": "note"}]$j$::jsonb, $j${"ask": true, "required": false, "label": "Yes, Welfare Avenue can email me news, volunteer call-outs and ways to help. I can unsubscribe at any time."}$j$::jsonb, $j$We’ll send you our sponsorship package and be in touch to plan it together.$j$, $j${"tags": ["gift-basket-drive", "sponsor prospect"], "campaign": "gift-basket-drive", "confirm": false, "request": {"type": "gift-drive", "title": "Gift drive, company", "who": "company"}}$j$::jsonb, 110, $j$sponsors$j$, 'Claude (16/10 drive forms)', 'Claude (16/10 drive forms)', now(), 'Claude for Steel (16/10/26: "pop up a form for each of those actions")'
 where not exists (select 1 from public.crm_forms where slug = $j$gift-drive-sponsor$j$);
insert into public.crm_forms (slug, title, intro, lang, kind, status, questions, consent, thank_you, settings, cover_photo_id, purpose, created_by, updated_by, published_at, published_by)
select $j$paniers-entreprises$j$, $j$Entreprises et commanditaires$j$, $j$Les entreprises rendent la collecte possible : des produits, du matériel d’emballage, une boîte de collecte ou une équipe qui vient emballer avec nous. Parlez-nous de votre entreprise et nous vous enverrons notre trousse de commandite.$j$, $j$fr$j$, $j$general$j$, 'published', $j$[{"id": "company", "type": "text", "label": "Entreprise ou organisme", "required": true}, {"id": "first_name", "type": "text", "label": "Votre prénom", "required": true, "to": "contact.first_name"}, {"id": "last_name", "type": "text", "label": "Votre nom", "required": true, "to": "contact.last_name"}, {"id": "email", "type": "email", "label": "Courriel", "required": true, "to": "contact.email"}, {"id": "role", "type": "text", "label": "Votre poste", "required": false}, {"id": "phone", "type": "phone", "label": "Téléphone", "required": false, "to": "contact.phone"}, {"id": "help_how", "type": "multi", "label": "Comment aimeriez-vous aider?", "required": true, "options": [{"v": "products", "l": "Donner des produits (en nature)"}, {"v": "supplies", "l": "Du matériel d’emballage"}, {"v": "team", "l": "Du bénévolat d’équipe (emballer avec nous)"}, {"v": "bin", "l": "Une boîte de collecte à vos bureaux"}, {"v": "money", "l": "Une commandite financière"}]}, {"id": "size", "type": "text", "label": "Quelle ampleur de soutien envisagez-vous?", "required": false, "help": "Un nombre d’articles, un budget ou la taille de votre équipe : tout nous aide à planifier."}, {"id": "message", "type": "long_text", "label": "Votre message", "required": false, "to": "note"}]$j$::jsonb, $j${"ask": true, "required": false, "label": "Oui, Welfare Avenue peut m’envoyer par courriel des nouvelles, des appels aux bénévoles et des façons d’aider. Je peux me désabonner en tout temps."}$j$::jsonb, $j$Nous vous enverrons notre trousse de commandite et vous écrirons pour planifier la suite ensemble.$j$, $j${"tags": ["gift-basket-drive", "sponsor prospect"], "campaign": "gift-basket-drive", "confirm": false, "request": {"type": "gift-drive", "title": "Gift drive, company", "who": "company"}}$j$::jsonb, 110, $j$sponsors$j$, 'Claude (16/10 drive forms)', 'Claude (16/10 drive forms)', now(), 'Claude for Steel (16/10/26: "pop up a form for each of those actions")'
 where not exists (select 1 from public.crm_forms where slug = $j$paniers-entreprises$j$);
insert into public.crm_forms (slug, title, intro, lang, kind, status, questions, consent, thank_you, settings, cover_photo_id, purpose, created_by, updated_by, published_at, published_by)
select $j$gift-drive-group$j$, $j$Schools and groups$j$, $j$Bring your class, club or team to collect donations, wrap gifts or volunteer together. Tell us about your group and we’ll find the right fit.$j$, $j$en$j$, $j$volunteer$j$, 'published', $j$[{"id": "group_name", "type": "text", "label": "Name of your group or organization", "required": true}, {"id": "group_type", "type": "choice", "label": "What kind of group is it?", "required": true, "options": [{"v": "school", "l": "School, college or university"}, {"v": "club", "l": "Club or association"}, {"v": "team", "l": "Sports team"}, {"v": "company", "l": "Company team"}, {"v": "faith", "l": "Faith group"}, {"v": "other", "l": "Something else"}]}, {"id": "first_name", "type": "text", "label": "Your first name", "required": true, "to": "contact.first_name"}, {"id": "last_name", "type": "text", "label": "Your last name", "required": true, "to": "contact.last_name"}, {"id": "email", "type": "email", "label": "Email", "required": true, "to": "contact.email"}, {"id": "phone", "type": "phone", "label": "Phone", "required": true, "to": "contact.phone", "help": "So we can reach you while we plan."}, {"id": "size", "type": "number", "label": "How many people?", "required": true, "help": "An estimate is fine."}, {"id": "activities", "type": "multi", "label": "What would your group like to do?", "required": true, "options": [{"v": "collect", "l": "Collect donations (a drive at your school or workplace)"}, {"v": "wrap", "l": "Wrap gifts at our December event"}, {"v": "volunteer", "l": "Volunteer as a group"}]}, {"id": "ages", "type": "choice", "label": "Ages in your group", "required": true, "options": [{"v": "adults", "l": "Everyone is 18 or older"}, {"v": "mixed", "l": "Some are under 18, with adult supervisors"}, {"v": "youth", "l": "Mostly under 18, with adult supervisors"}]}, {"id": "timing", "type": "text", "label": "When would suit your group?", "required": false, "help": "Donations come in from mid to end of November; wrapping is in December."}, {"id": "comments", "type": "long_text", "label": "Anything else we should know?", "required": false, "to": "note"}]$j$::jsonb, $j${"ask": true, "required": false, "label": "Yes, Welfare Avenue can email me news, volunteer call-outs and ways to help. I can unsubscribe at any time."}$j$::jsonb, $j$We have your group’s details, and our team will be in touch to plan it with you.$j$, $j${"tags": ["gift-basket-drive", "group sign-up"], "campaign": "gift-basket-drive", "volunteer_record": false, "confirm": false, "request": {"type": "gift-drive", "title": "Gift drive, group", "who": "group_name", "count": "size", "count_word": "people"}}$j$::jsonb, 102, $j$groups$j$, 'Claude (16/10 drive forms)', 'Claude (16/10 drive forms)', now(), 'Claude for Steel (16/10/26: "pop up a form for each of those actions")'
 where not exists (select 1 from public.crm_forms where slug = $j$gift-drive-group$j$);
insert into public.crm_forms (slug, title, intro, lang, kind, status, questions, consent, thank_you, settings, cover_photo_id, purpose, created_by, updated_by, published_at, published_by)
select $j$paniers-groupes$j$, $j$Écoles et groupes$j$, $j$Venez avec votre classe, votre club ou votre équipe pour recueillir des dons, emballer des cadeaux ou faire du bénévolat ensemble. Parlez-nous de votre groupe et nous trouverons la bonne formule.$j$, $j$fr$j$, $j$volunteer$j$, 'published', $j$[{"id": "group_name", "type": "text", "label": "Nom de votre groupe ou organisme", "required": true}, {"id": "group_type", "type": "choice", "label": "De quel type de groupe s’agit-il?", "required": true, "options": [{"v": "school", "l": "École, cégep ou université"}, {"v": "club", "l": "Club ou association"}, {"v": "team", "l": "Équipe sportive"}, {"v": "company", "l": "Équipe d’entreprise"}, {"v": "faith", "l": "Groupe confessionnel"}, {"v": "other", "l": "Autre chose"}]}, {"id": "first_name", "type": "text", "label": "Votre prénom", "required": true, "to": "contact.first_name"}, {"id": "last_name", "type": "text", "label": "Votre nom", "required": true, "to": "contact.last_name"}, {"id": "email", "type": "email", "label": "Courriel", "required": true, "to": "contact.email"}, {"id": "phone", "type": "phone", "label": "Téléphone", "required": true, "to": "contact.phone", "help": "Pour vous joindre pendant la planification."}, {"id": "size", "type": "number", "label": "Combien de personnes?", "required": true, "help": "Une estimation suffit."}, {"id": "activities", "type": "multi", "label": "Que voudrait faire votre groupe?", "required": true, "options": [{"v": "collect", "l": "Recueillir des dons (une collecte à votre école ou à vos bureaux)"}, {"v": "wrap", "l": "Emballer des cadeaux à notre événement de décembre"}, {"v": "volunteer", "l": "Faire du bénévolat en groupe"}]}, {"id": "ages", "type": "choice", "label": "L’âge des membres du groupe", "required": true, "options": [{"v": "adults", "l": "Tout le monde a 18 ans ou plus"}, {"v": "mixed", "l": "Certains ont moins de 18 ans, avec des adultes responsables"}, {"v": "youth", "l": "La plupart ont moins de 18 ans, avec des adultes responsables"}]}, {"id": "timing", "type": "text", "label": "Quand cela conviendrait-il à votre groupe?", "required": false, "help": "Les dons arrivent de la mi-novembre à la fin novembre; l’emballage a lieu en décembre."}, {"id": "comments", "type": "long_text", "label": "Autre chose à nous dire?", "required": false, "to": "note"}]$j$::jsonb, $j${"ask": true, "required": false, "label": "Oui, Welfare Avenue peut m’envoyer par courriel des nouvelles, des appels aux bénévoles et des façons d’aider. Je peux me désabonner en tout temps."}$j$::jsonb, $j$Nous avons les détails de votre groupe et notre équipe vous écrira pour planifier le tout avec vous.$j$, $j${"tags": ["gift-basket-drive", "group sign-up"], "campaign": "gift-basket-drive", "volunteer_record": false, "confirm": false, "request": {"type": "gift-drive", "title": "Gift drive, group", "who": "group_name", "count": "size", "count_word": "people"}}$j$::jsonb, 102, $j$groups$j$, 'Claude (16/10 drive forms)', 'Claude (16/10 drive forms)', now(), 'Claude for Steel (16/10/26: "pop up a form for each of those actions")'
 where not exists (select 1 from public.crm_forms where slug = $j$paniers-groupes$j$);

