insert into public.change_log (entity_type, entity_id, field, old_value, new_value, changed_by)
select 'crm_form', f.id::text, 'published', null, f.slug || ' (' || f.title || ', ' || f.lang || ', group ' || f.purpose || '): the Holiday Gift Basket Drive page''s pop-up form', 'Claude (16/10 drive forms)'
  from public.crm_forms f where f.slug in ('gift-drive-give', 'paniers-donner', 'gift-drive-volunteer', 'paniers-benevole', 'gift-drive-sponsor', 'paniers-entreprises', 'gift-drive-group', 'paniers-groupes')
   and not exists (select 1 from public.change_log c where c.entity_type = 'crm_form' and c.entity_id = f.id::text and c.field = 'published' and c.changed_by = 'Claude (16/10 drive forms)');
